\begin{thm}[Arithmetical induction]\ollabel{thm:dedinfiniteinduction}
Let $N, s, o$ comprise a Dedekind algebra. Then for any set $X$:  
	\begin{center}
		if $o \in X$ and $(\forall {n} \in N \cap X){s}({n}) \in X$, {then} $N \subseteq X$.
	\end{center}
\end{thm}

