\begin{thm}[استقرای حسابی]\ollabel{thm:dedinfiniteinduction}
فرض کنید $N, s, o$ یک جبر ددکیند را تشکیل دهند. آنگاه برای هر مجموعهٔ
$X$:
	\begin{center}
		اگر $o \in X$ و $(\forall {n} \in N \cap X){s}({n}) \in X$، {آنگاه} $N \subseteq X$.
	\end{center}
\end{thm}

